package org.apache.commons.math.optimization.general;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxEvaluationsExceededException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.exception.LocalizedFormats;
import org.apache.commons.math.linear.InvalidMatrixException;
import org.apache.commons.math.linear.LUDecompositionImpl;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.optimization.DifferentiableMultivariateVectorialOptimizer;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.SimpleVectorialValueChecker;
import org.apache.commons.math.optimization.VectorialConvergenceChecker;
import org.apache.commons.math.optimization.VectorialPointValuePair;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for AbstractLeastSquaresOptimizer.getRMS()
 */
public class AbstractLeastSquaresOptimizer_getRMS_TriageGen1Test {

    private AbstractLeastSquaresOptimizer optimizer;

    // Concrete implementation of the abstract class for testing purposes
    private static class TestOptimizer extends AbstractLeastSquaresOptimizer {
        @Override
        protected org.apache.commons.math3.optim.PointValuePair doOptimize() {
            return null;
        }
    }

    @Before
    public void setUp() {
        optimizer = new TestOptimizer();
    }

    /**
     * Helper method to set private fields via reflection since the class is abstract
     * and fields are likely protected/private.
     */
    private void setPrivateField(String fieldName, Object value) throws Exception {
        Field field = AbstractLeastSquaresOptimizer.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(optimizer, value);
    }

    @Test
    public void testGetRMS_StandardCalculation() throws Exception {
        int rows = 3;
        double[] residuals = {1.0, 2.0, 3.0};
        double[] weights = {1.0, 0.5, 2.0};

        setPrivateField("rows", rows);
        setPrivateField("residuals", residuals);
        setPrivateField("residualsWeights", weights);

        // criterion = (1.0^2 * 1.0) + (2.0^2 * 0.5) + (3.0^2 * 2.0)
        // criterion = 1.0 + 2.0 + 18.0 = 21.0
        // rms = sqrt(21.0 / 3) = sqrt(7.0)
        double expected = Math.sqrt(7.0);
        double actual = optimizer.getRMS();

        assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetRMS_ZeroResiduals() throws Exception {
        int rows = 2;
        double[] residuals = {0.0, 0.0};
        double[] weights = {1.0, 1.0};

        setPrivateField("rows", rows);
        setPrivateField("residuals", residuals);
        setPrivateField("residualsWeights", weights);

        assertEquals(0.0, optimizer.getRMS(), 1e-12);
    }

    @Test
    public void testGetRMS_ZeroWeights() throws Exception {
        int rows = 2;
        double[] residuals = {10.0, 10.0};
        double[] weights = {0.0, 0.0};

        setPrivateField("rows", rows);
        setPrivateField("residuals", residuals);
        setPrivateField("residualsWeights", weights);

        assertEquals(0.0, optimizer.getRMS(), 1e-12);
    }

    @Test
    public void testGetRMS_SingleElement() throws Exception {
        int rows = 1;
        double[] residuals = {4.0};
        double[] weights = {0.25};

        setPrivateField("rows", rows);
        setPrivateField("residuals", residuals);
        setPrivateField("residualsWeights", weights);

        // criterion = 4^2 * 0.25 = 16 * 0.25 = 4
        // rms = sqrt(4 / 1) = 2
        assertEquals(2.0, optimizer.getRMS(), 1e-12);
    }

    @Test
    public void testGetRMS_EmptyRows() throws Exception {
        // Testing behavior when rows = 0 to check for division by zero (NaN)
        setPrivateField("rows", 0);
        setPrivateField("residuals", new double[0]);
        setPrivateField("residualsWeights", new double[0]);

        double actual = optimizer.getRMS();
        assertEquals(Double.NaN, actual, 0.0);
    }

    @Test
    public void testGetRMS_LargeValues() throws Exception {
        int rows = 1;
        double[] residuals = {1e10};
        double[] weights = {1.0};

        setPrivateField("rows", rows);
        setPrivateField("residuals", residuals);
        setPrivateField("residualsWeights", weights);

        // sqrt(1e20 / 1) = 1e10
        assertEquals(1e10, optimizer.getRMS(), 1e-2);
    }
}
